// Pull yesterday's customers + live bets + leads needing follow-up.
const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const hdr = { apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}` };
const yesterdayIso = new Date(Date.now() - 86400000).toISOString();
const [customers, bets, leadsRes, councilRes] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?select=product,kind,mrr_usd,became_paid_at,churned_at&limit=500`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/bets?status=eq.live&select=hypothesis,kind,started_at,time_box_days,est_mrr_impact_usd&order=started_at.desc&limit=50`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/leads?status=in.(ready,contacted,conversation)&select=full_name,company,tier,follow_up_at&order=follow_up_at.asc.nullslast&limit=20`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?kind=eq.paid&churned_at=is.null&select=full_name,email,product,mrr_usd,became_paid_at&order=mrr_usd.desc.nullslast&limit=10`, headers: hdr, json: true }),
]);
const paidAddedYesterday = customers.filter(c => c.kind === 'paid' && c.became_paid_at >= yesterdayIso);
const churnedYesterday   = customers.filter(c => c.kind === 'churned' && c.churned_at >= yesterdayIso);
const yesterdayMrr = paidAddedYesterday.reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0) - churnedYesterday.reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0);
return [{ json: { customers, bets, leads: leadsRes, council: councilRes, yesterday_mrr_delta_usd: yesterdayMrr } }];

const blocks = $input.first().json.content || [];
const text = blocks.map(b => b.text || '').join('').trim();
let brief = null;
try {
  const a = text.indexOf('{'); const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) brief = JSON.parse(text.slice(a, b + 1));
} catch { brief = null; }
brief = brief || { body: text };
brief.yesterday_mrr_delta_usd = $('Pull live data').item.json.yesterday_mrr_delta_usd || 0;
return [{ json: { brief, telegram_text: 'Today: ' + (brief.one_bet || brief.body || 'No brief.') + (brief.one_customer ? '\nTalk to: ' + brief.one_customer : '') + (brief.one_anti_action ? '\nDon\'t: ' + brief.one_anti_action : '') + (brief.yesterday_mrr_delta_usd ? '\nYesterday: $' + Math.round(brief.yesterday_mrr_delta_usd) + ' MRR' : '') } }];
